{
  "id": "convertToCelsius",
  "type": "core.action.script",
  "typeVersion": "1.0",
  "display": {
    "label": "Convert to Celsius"
  },
  "inputs": {
    "script": "const tempF = $vars.getWeather.output.body.current.temperature_2m;\nconst tempC = Math.round((tempF - 32) * 5 / 9 * 10) / 10;\nreturn { temperatureF: tempF, temperatureC: tempC };"
  },
  "outputs": {
    "output": {
      "type": "object",
      "description": "The return value of the script",
      "source": {
        "type": "literal",
        "expression": "=result.response",
        "fieldType": "string"
      },
      "var": "output"
    },
    "error": {
      "type": "object",
      "description": "Error information if the script fails",
      "source": {
        "type": "literal",
        "expression": "=result.Error",
        "fieldType": "string"
      },
      "var": "error"
    }
  },
  "model": {
    "type": "bpmn:ScriptTask"
  }
},
{
  "id": "formatSummary",

